             item(f"{B}-P2", 3, "The concept was first put into practice in North America.", "NOT GIVEN", "European and North American cities are mentioned, but not where the idea was first applied.", "The passage gives no information about which region used the idea first.", "detail discrimination", "tfng"),
             item(f"{B}-P2", 4, "Researchers are confident that the social benefits reported by residents are caused by the design of their neighbourhood.", "FALSE", "researchers caution that it is difficult to separate the influence of urban design from that of income, age and length of residence", "Researchers say the cause is hard to identify, which contradicts 'confident'.", "detail discrimination", "tfng"),
             item(f"{B}-P2", 5, "According to some critics, a short walk or cycle from home may not reach the places where many people work.", "TRUE", "a fifteen-minute radius may cover shopping and schooling but not employment", "'Places where many people work' paraphrases 'employment'.", "paraphrase recognition", "tfng"),
             item(f"{B}-P2", 6, "Summary: Critics argue that the approach suits compact, older city centres better than car-dependent (6) ______.", "A", "than in suburbs built around the car", "'Car-dependent suburbs' paraphrases 'suburbs built around the car'. Villages are not mentioned, and the critics' contrast is between city centres and suburbs.", "paraphrase recognition", "matching", options=list("ABCDEFGH")),
